const listingTags = item => Array.isArray(item.tags) ? item.tags : [item.tag].filter(Boolean);
const searchedTagTerms = () => (tagSearch.value.match(/#?[a-z0-9-]+/gi) || []).map(value => value.replace('#', '').toLowerCase());
const filtered = () => listings.filter(item => { const itemTags = listingTags(item).map(tag => tag.toLowerCase()); const typedTags = searchedTagTerms(); const matches = terms => !terms.length || (tagMatchMode === 'all' ? terms.every(term => itemTags.some(tag => tag.includes(term))) : terms.some(term => itemTags.some(tag => tag.includes(term)))); return (activeCategory === 'All' || item.category === activeCategory) && `${item.title} ${item.description} ${itemTags.join(' ')}`.toLowerCase().includes(activeQuery.toLowerCase()) && matches(activeTags) && matches(typedTags) && lockedTags.every(tag => itemTags.some(itemTag => itemTag.includes(tag))) && !voidTags.some(tag => itemTags.some(itemTag => itemTag.includes(tag))); }).sort((left, right) => { const leftDate = new Date(left.createdAt || 0).valueOf(); const rightDate = new Date(right.createdAt || 0).valueOf(); if (sortMode === 'oldest') return leftDate - rightDate; if (sortMode === 'popular') return ((right.likes?.length || 0) + (right.favorites?.length || 0) + stateFor(right.id).score) - ((left.likes?.length || 0) + (left.favorites?.length || 0) + stateFor(left.id).score); return rightDate - leftDate; });
const stateFor = id => postState[id] || (postState[id] = { score: 0, vote: 0, comments: [] });
const savePostState = () => localStorage.setItem('collector-marketplace-post-state', JSON.stringify(postState));
const card = item => { const state = stateFor(item.id); const owner = item.owner?.username || item.ownerName || 'collector'; const avatar = owner.slice(0, 1).toUpperCase(); const imageCount = item.images?.length || 1; const videoCount = item.videos?.length || 0; const commentCount = Number(item.commentCount || 0); return `<article class="listing"><header class="collector-head"><b>${safe(avatar)}</b><div><strong>@${safe(owner)} <em>CURATOR</em></strong><small>★★★★★ <i>(${item.owner?.reputation || 0})</i></small></div><time datetime="${safe(item.createdAt || '')}">${safe(formatListingDate(item.createdAt))}</time></header><div class="listing-main"><button class="media" data-detail="${item.id}"><img src="${safe(item.image)}" alt="${safe(item.title)}"><span class="grade">${safe(item.category)}</span>${imageCount > 1 || videoCount ? `<span class="image-count">${imageCount} photo${imageCount === 1 ? '' : 's'}${videoCount ? ` · ${videoCount} video${videoCount === 1 ? '' : 's'}` : ''}</span>` : ''}</button><section class="listing-copy"><h2>${safe(item.title)}</h2><div class="meta">COLLECTORMARKETPLACE.NET</div><p><b>@${safe(owner)} ★★★★★</b><br>${safe(item.description)}</p><footer class="listing-actions"><button class="listing-action action-buy" data-purchase="${item.id}"><span>BUY</span><b>$${item.price}</b></button><button class="listing-action" data-trade="${item.id}"><span>⇄</span> TRADE</button><span class="vote-control"><button type="button" class="listing-action vote ${state.vote === 1 ? 'selected' : ''}" data-vote="up" data-post="${item.id}" aria-label="Upvote ${safe(item.title)}">▲</button><output>${state.score}</output><button type="button" class="listing-action vote ${state.vote === -1 ? 'selected' : ''}" data-vote="down" data-post="${item.id}" aria-label="Downvote ${safe(item.title)}">▼</button></span><button type="button" class="listing-action favorite-button ${state.favorite ? 'selected' : ''}" data-favorite="${item.id}" aria-pressed="${state.favorite ? 'true' : 'false'}" aria-label="Favorite ${safe(item.title)}">♥</button><button type="button" class="listing-action comment-button" data-comments="${item.id}" aria-label="${commentCount} comments on ${safe(item.title)}">◌ <b>${commentCount}</b> <span>COMMENTS</span></button></footer></section></div></article>`; };

function renderCategories() { const types = ['All', ...[...new Set([...categoryOptions, ...listings.map(item => item.category)])].sort((left, right) => left.localeCompare(right))]; categories.innerHTML = types.map(type => `<button class="${type === activeCategory ? 'active' : ''}" data-category="${safe(type)}">${safe(type)}</button>`).join(''); }
function renderTags(filter = tagSearch.value) { const match = filter.trim().replace(/#/g, '').toLowerCase(); const available = new Set([...categoryOptions, ...listings.flatMap(listingTags)]); const bottomGroups = ['Artisan Alcohol (21+ Only)', 'Adult Only (18+)']; const grouped = Object.entries(tagGroups).sort(([left], [right]) => { const leftRank = bottomGroups.indexOf(left); const rightRank = bottomGroups.indexOf(right); if (leftRank !== -1 || rightRank !== -1) return (leftRank === -1 ? -1 : leftRank) - (rightRank === -1 ? -1 : rightRank); const sortNames = { 'Fashion & Luxury': 'Fashion 01', Styles: 'Fashion 02', 'Art, History & Materials': 'Fashion 03', 'Shoes & Sneakers': 'Fashion 03.5', 'Food & Drink': 'Fashion 04', 'Top Brands': 'Artisan Cheese', 'Artisan Cheese': 'Top Brands' }; const sortName = name => sortNames[name] || name; return sortName(left).localeCompare(sortName(right)); }).map(([name, values]) => [name, values.filter(tag => available.has(tag) && tag.toLowerCase().includes(match)).sort((left, right) => left.localeCompare(right))]).filter(([name, values]) => values.length || (name === 'Top Brands' && !match)); tags.innerHTML = grouped.length ? grouped.map(([name, values]) => `<section class="tag-group"><h3>${safe(name)}</h3><div class="tag-group-buttons">${values.length ? values.map(tag => { const selected = activeTags.includes(tag.toLowerCase()); return `<button type="button" class="${selected ? 'active' : ''}" data-tag="${safe(tag)}" aria-pressed="${selected}">#${safe(tag)}</button>`; }).join('') : '<span class="empty-tag">Brand tags coming soon.</span>'}</div></section>`).join('') : '<span class="empty-tag">No tags found.</span>'; }
function renderFeed(reset = true) { const rows = filtered(); if (reset) page = 1; const visible = rows.slice(0, page * 4); stream.innerHTML = visible.map(card).join('') || '<p class="load-state">No collector finds match that search.</p>'; stream.querySelectorAll('.collector-head').forEach((header, index) => { header.dataset.profile = visible[index]?.ownerId || ''; header.tabIndex = 0; header.setAttribute('role', 'button'); header.setAttribute('aria-label', `Open ${visible[index]?.owner?.username || 'collector'} profile`); }); document.querySelector('#result-count').textContent = `${rows.length} listed`; sentinel.textContent = page * 4 < rows.length ? 'Scroll for more finds ↓' : 'You are all caught up.'; }
function openModal(title, copy, form) { modal.className = ''; document.body.classList.remove('purchase-open', 'comments-open'); modalContent.innerHTML = `<h2 class="modal-title">${title}</h2><p class="modal-copy">${copy}</p>${form || ''}`; if (!modal.open) modal.showModal(); if (form?.includes('listing-form')) { const primaryTag = modalContent.querySelector('[name="category"]'); const extraTags = modalContent.querySelector('[name="tags"]'); primaryTag?.closest('label')?.firstChild && (primaryTag.closest('label').firstChild.textContent = 'Tags · start with one primary tag'); if (primaryTag) primaryTag.placeholder = 'Add your first tag'; extraTags?.closest('label')?.firstChild && (extraTags.closest('label').firstChild.textContent = 'More tags '); const required = modalContent.querySelector('.listing-publish-bar span'); if (required) required.textContent = 'Required: title, at least one tag, price, description, and at least one photo.'; } }
function openAuthPanel(mode = 'signup') { const login = mode === 'login'; openModal(login ? 'Sign in' : 'Create your account', login ? 'Sign in to list items, comment, and manage trades.' : 'Create your collector profile to list items, comment, and trade.', `<form class="modal-form auth-form" data-mode="${mode}">${login ? '' : '<input required name="username" placeholder="Collector username">'}<input required name="email" type="email" placeholder="Email address"><label class="password-field"><input required name="password" type="password" minlength="8" placeholder="Password (8+ characters)" autocomplete="${login ? 'current-password' : 'new-password'}"><button type="button" data-password-toggle aria-label="Show password" aria-pressed="false">◉</button></label><button>${login ? 'Sign in' : 'Create account'}</button></form><button type="button" class="auth-switch" data-auth-switch="${login ? 'signup' : 'login'}">${login ? 'Need an account? Create one' : 'Already a member? Sign in'}</button>`); }
async function openAccountPanel() { if (!session?.user) return openAuthPanel(); const user = session.user; const ownListings = listings.filter(item => item.ownerId === user.id); const [connections, suggestions] = await Promise.all([api(`/user/${user.id}/connections`).catch(() => ({ friends: [], following: [] })), api('/users/suggestions').catch(() => [])]); const people = rows => rows.length ? rows.map(person => `<button type="button" class="connection-row" data-profile="${person.id}">${accountAvatar(person, 'connection-avatar')}<span><b>@${safe(person.username)}</b><small>${Number(person.reputation || 0)} reputation</small></span></button>`).join('') : '<p class="modal-copy">No collectors here yet.</p>'; const suggested = suggestions.length ? suggestions.map(person => `<article class="suggested-account">${accountAvatar(person, 'connection-avatar')}<div><strong>@${safe(person.username)}</strong><small>${Number(person.activeListingCount || 0)} active posts · ${Number(person.reputation || 0)} reputation</small></div><button type="button" data-account-follow="${person.id}">Follow</button></article>`).join('') : '<p class="modal-copy">No new collectors to suggest right now.</p>'; openModal('Your account', 'Manage your profile, collector connections, and marketplace activity.', `<section class="account-workspace"><header class="account-hero">${accountAvatar(user, 'account-avatar account-avatar-large')}<div><p>COLLECTOR PROFILE</p><h3>@${safe(user.username)}</h3><span>${safe(user.bio || 'Add a short bio to introduce your collection.')} · Reputation ${Number(user.reputation || 0)}</span></div><button type="button" data-account-edit>Edit profile</button></header><div class="account-stats"><span><b>${ownListings.length}</b>Posts</span><span><b>${connections.friends.length}</b>Friends</span><span><b>${connections.following.length}</b>Following</span></div><section class="account-columns"><section><h3>Following <small>${connections.following.length}</small></h3><div class="account-scroll">${people(connections.following)}</div></section><section><h3>Friends <small>${connections.friends.length}</small></h3><div class="account-scroll">${people(connections.friends)}</div></section><section><h3>Discover collectors</h3><div class="account-scroll">${suggested}</div></section><section><h3>Your posts <small>${ownListings.length}</small></h3><div class="account-scroll">${ownListings.length ? ownListings.map(item => `<button type="button" class="account-post" data-detail="${item.id}">${safe(item.title)} <span>$${safe(item.price)}</span></button>`).join('') : '<p class="modal-copy">List your first item to see it here.</p>'}</div></section></section><footer class="account-actions"><button type="button" data-delivery-center>Delivery center</button><button type="button" data-chat>Open messages</button><button type="button" data-signout>Sign out</button></footer></section>`); modal.classList.add('account-dialog'); document.body.classList.add('account-open'); }
async function openProfile(id) { if (!id) return; if (session?.user?.id === id) return openAccountPanel(); const profile = await api(`/user/${id}`); const following = Boolean(session?.user?.following?.includes(id)); const posts = profile.activeListings.length ? profile.activeListings.map(item => `<p class="account-post">${safe(item.title)} · $${safe(item.price)}</p>`).join('') : '<p class="modal-copy">No active listings.</p>'; openModal(`@${safe(profile.username)}`, `${safe(profile.bio || 'Collector profile')} · Reputation ${profile.reputation || 0}`, `<section class="account-panel"><div class="account-identity"><b>${safe(profile.avatar || profile.username.slice(0, 2).toUpperCase())}</b><div><strong>@${safe(profile.username)}</strong><span>${profile.activeListings.length} active posts · ${profile.tradeHistory.length} completed trades</span></div>${session ? `<button type="button" data-follow="${profile.id}">${following ? 'Following' : 'Follow'}</button>` : ''}</div><div class="social-lists"><section><h3>Active posts <small>${profile.activeListings.length}</small></h3>${posts}</section></div></section>${session ? `<button type="button" class="auth-switch" data-collector-chat="${profile.id}">Message collector</button>` : ''}`); }
function imageUrls(value) { return value.split(/[\n,]+/).map(url => url.trim()).filter(url => /^https?:\/\//i.test(url)); }
function renderImagePreview(images = [], videos = []) { const preview = document.querySelector('#listing-image-preview'); if (!preview) return; const photos = images.map((url, index) => `<figure class="preview-card"><img src="${safe(url)}" alt="Listing image preview ${index + 1}"><figcaption>Photo ${index + 1}${url.startsWith('data:') ? ' · uploaded' : ' · link'}</figcaption></figure>`).join(''); const clips = videos.map((url, index) => `<figure class="preview-card preview-video"><video src="${safe(url)}" controls preload="metadata"></video><figcaption>Video ${index + 1} · uploaded</figcaption></figure>`).join(''); preview.innerHTML = photos || clips ? photos + clips : '<div class="preview-empty"><b>Add listing media</b><span>Upload up to 5 photos and one short video, or paste image links.</span></div>'; }
async function optimizeListingImage(file) { if (!file.type.startsWith('image/')) throw new Error(`${file.name} is not an image.`); if (file.size > 8 * 1024 * 1024) throw new Error(`${file.name} is larger than 8 MB.`); const source = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(new Error(`Could not read ${file.name}.`)); reader.readAsDataURL(file); }); const image = await new Promise((resolve, reject) => { const element = new Image(); element.onload = () => resolve(element); element.onerror = () => reject(new Error(`Could not prepare ${file.name}.`)); element.src = source; }); const scale = Math.min(1, 1600 / Math.max(image.width, image.height)); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round(image.width * scale)); canvas.height = Math.max(1, Math.round(image.height * scale)); canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height); return canvas.toDataURL('image/jpeg', .82); }
async function prepareListingFiles(files) { const selected = [...files]; if (selected.length > 5) throw new Error('Choose up to 5 photos per listing.'); uploadedListingImages = await Promise.all(selected.map(optimizeListingImage)); const linked = imageUrls(document.querySelector('[name="imageUrls"]')?.value || ''); if (linked.length + uploadedListingImages.length > 5) { uploadedListingImages = uploadedListingImages.slice(0, Math.max(0, 5 - linked.length)); } renderImagePreview([...uploadedListingImages, ...linked], uploadedListingVideos); }
async function prepareListingVideo(files) { const [file] = [...files]; if (!file) { uploadedListingVideos = []; syncListingPreview(); return; } if (files.length > 1) throw new Error('Choose one short video per listing.'); if (!['video/mp4', 'video/webm', 'video/quicktime'].includes(file.type)) throw new Error('Use an MP4, WEBM, or MOV video.'); if (file.size > 4 * 1024 * 1024) throw new Error('Keep listing videos under 4 MB.'); const video = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(new Error(`Could not read ${file.name}.`)); reader.readAsDataURL(file); }); uploadedListingVideos = [video]; syncListingPreview(); }
function syncListingPreview() { const linked = imageUrls(document.querySelector('[name="imageUrls"]')?.value || ''); renderImagePreview([...uploadedListingImages, ...linked].slice(0, 5), uploadedListingVideos); }
function openListingForm() { if (!session) return openAuthPanel('login'); uploadedListingImages = []; uploadedListingVideos = []; openModal('Create a listing', 'Build a complete collector-ready listing. Add photos, a short video, and the details buyers need.', '<form class="modal-form listing-form"><datalist id="listing-categories"><option>Sports Cards</option><option>Memorabilia</option><option>Books</option><option>Comics</option><option>Vintage</option><option>Art</option></datalist><section class="listing-editor-grid"><div class="listing-details"><p class="listing-step">01 · LISTING DETAILS</p><section class="listing-form-grid"><label class="title-field">Listing title<input required name="title" maxlength="120" placeholder="e.g. 1964 Topps Mickey Mantle"></label><label>Category<input required name="category" list="listing-categories" placeholder="Choose a category"></label><label>Price (USD)<input required name="price" type="number" min="0" step="0.01" placeholder="0.00"></label></section><p class="listing-step">02 · ADD MEDIA</p><section class="listing-media-inputs"><label class="listing-upload-field"><span>Photos <i>Up to 5 · JPG, PNG, WEBP</i></span><input name="imageFiles" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label class="listing-upload-field"><span>Short video <i>1 MP4, WEBM, or MOV · 4 MB max</i></span><input name="videoFiles" type="file" accept="video/mp4,video/webm,video/quicktime"></label><label class="listing-image-field">Image links <i>Optional · one link per line</i><textarea name="imageUrls" placeholder="https://example.com/front.jpg\nhttps://example.com/back.jpg"></textarea></label></section><p class="listing-step">03 · TELL THE STORY</p><label class="description-field">Description<textarea required name="description" maxlength="2000" placeholder="Describe condition, defects, provenance, and anything collectors should know."></textarea></label><label class="check listing-trade-option"><input name="tradeOffer" type="checkbox"> Open to trade offers</label></div><aside class="listing-media-panel"><div><p class="listing-step">MEDIA PREVIEW</p><h3>Your listing gallery</h3><p>Photos and video will appear exactly as collectors see them.</p></div><div id="listing-image-preview" class="listing-image-preview"><div class="preview-empty"><b>Add listing media</b><span>Upload up to 5 photos and one short video, or paste image links.</span></div></div></aside></section><footer class="listing-publish-bar"><span>Required: title, category, price, description, and at least one photo.</span><button>Publish listing</button></footer></form>'); modal.classList.add('listing-dialog'); }
const listingTagOptions = () => [...new Set(categoryOptions)].sort((left, right) => left.localeCompare(right)).map(tag => `<option value="${safe(tag)}">`).join('');
const parseListingTags = (value, category) => [...new Set([String(category || '').trim(), ...String(value || '').split(/[\n,]+/).map(tag => tag.trim().replace(/^#/, '')).filter(Boolean)])].slice(0, 8);
function openListingForm() { if (!session) return openAuthPanel('login'); uploadedListingImages = []; uploadedListingVideos = []; const options = listingTagOptions(); openModal('Create a listing', 'Build a complete collector-ready listing. Add photos, a short video, and the details buyers need.', `<form class="modal-form listing-form"><datalist id="listing-categories">${options}</datalist><datalist id="listing-tags">${options}</datalist><section class="listing-editor-grid"><div class="listing-details"><p class="listing-step">01 · LISTING DETAILS</p><section class="listing-form-grid"><label class="title-field">Listing title<input required name="title" maxlength="120" placeholder="e.g. 1964 Topps Mickey Mantle"></label><label>Category<input required name="category" list="listing-categories" placeholder="Choose a category"></label><label>Price (USD)<input required name="price" type="number" min="0" step="0.01" placeholder="0.00"></label><label class="listing-tag-field">Tags <i>Up to 7 extra · separate with commas</i><input name="tags" list="listing-tags" maxlength="420" placeholder="e.g. Sports Cards, Vintage, Limited Edition"></label></section><p class="listing-step">02 · ADD MEDIA</p><section class="listing-media-inputs"><label class="listing-upload-field"><span>Photos <i>Up to 5 · JPG, PNG, WEBP</i></span><input name="imageFiles" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label class="listing-upload-field"><span>Short video <i>1 MP4, WEBM, or MOV · 4 MB max</i></span><input name="videoFiles" type="file" accept="video/mp4,video/webm,video/quicktime"></label><label class="listing-image-field">Image links <i>Optional · one link per line</i><textarea name="imageUrls" placeholder="https://example.com/front.jpg\nhttps://example.com/back.jpg"></textarea></label></section><p class="listing-step">03 · TELL THE STORY</p><label class="description-field">Description<textarea required name="description" maxlength="2000" placeholder="Describe condition, defects, provenance, and anything collectors should know."></textarea></label><label class="check listing-trade-option"><input name="tradeOffer" type="checkbox"> Open to trade offers</label></div><aside class="listing-media-panel"><div><p class="listing-step">MEDIA PREVIEW</p><h3>Your listing gallery</h3><p>Photos and video will appear exactly as collectors see them.</p></div><div id="listing-image-preview" class="listing-image-preview"><div class="preview-empty"><b>Add listing media</b><span>Upload up to 5 photos and one short video, or paste image links.</span></div></div></aside></section><footer class="listing-publish-bar"><span>Required: title, category, price, description, and at least one photo.</span><button>Publish listing</button></footer></form>`); modal.classList.add('listing-dialog'); }
function renderCommentThread(comments, listingId, parentId = null, depth = 0) { return comments.filter(comment => (comment.parentId || null) === parentId).map(comment => `<article class="post-comment ${depth ? 'is-reply' : ''}" data-comment-id="${comment.id}"><div><b>@${safe(comment.user?.username || 'collector')}</b><time>${new Date(comment.createdAt || Date.now()).toLocaleDateString()}</time></div><p>${safe(comment.body)}</p><footer class="comment-actions"><span class="comment-votes"><button type="button" class="comment-vote ${comment.myVote === 1 ? 'selected' : ''}" data-comment-vote="1" data-comment="${comment.id}" data-comment-listing="${listingId}" aria-label="Upvote comment">▲</button><output>${Number(comment.score || 0)}</output><button type="button" class="comment-vote ${comment.myVote === -1 ? 'selected' : ''}" data-comment-vote="-1" data-comment="${comment.id}" data-comment-listing="${listingId}" aria-label="Downvote comment">▼</button></span><button type="button" class="comment-reply" data-comment-reply="${comment.id}" data-comment-listing="${listingId}">Reply</button></footer>${renderCommentThread(comments, listingId, comment.id, depth + 1)}</article>`).join(''); }
async function openComments(item, replyTo = '') { let comments = []; try { comments = await api(`/comments/${item.id}`); } catch { comments = stateFor(item.id).comments.map(body => ({ body, user: { username: 'collector' }, parentId: null })); } const thread = comments.length ? renderCommentThread(comments, item.id) : '<p class="modal-copy">No comments yet. Start the conversation.</p>'; const replyLabel = replyTo ? '<p class="modal-copy">Replying in this thread.</p>' : ''; openModal(`Comments · ${item.title}`, replyLabel + thread, `<form class="modal-form comment-form" data-post="${item.id}" data-parent="${replyTo}"><textarea required maxlength="500" placeholder="${replyTo ? 'Write a reply' : 'Add a comment'}"></textarea><button type="submit">${replyTo ? 'Post reply' : 'Post comment'}</button></form>`); modal.classList.add('comment-dialog'); document.body.classList.add('comments-open'); }
async function openChatCenter() { if (!session) return openAuthPanel('login'); try { const [trades, currentDeliveries, conversations, suggestions] = await Promise.all([api('/trades'), api('/deliveries'), api('/conversations'), api('/users/suggestions')]); deliveries = currentDeliveries; const collectorRows = conversations.map(conversation => { const other = conversation.otherUser || {}; const lastMessage = conversation.messages.at(-1); return `<button type="button" class="chat-conversation-row" data-conversation="${conversation.id}"><span class="chat-avatar">${safe((other.username || 'C').slice(0, 1).toUpperCase())}</span><span><strong>@${safe(other.username || 'collector')}</strong><small>${safe(lastMessage?.body || 'Start a conversation')}</small></span><i>Open</i></button>`; }).join(''); const suggestedRows = suggestions.map(user => `<button type="button" class="suggestion-card" data-collector-chat="${user.id}"><span class="chat-avatar">${safe((user.username || 'C').slice(0, 1).toUpperCase())}</span><span><strong>@${safe(user.username || 'collector')}</strong><small>${Number(user.activeListingCount || 0)} active listing${Number(user.activeListingCount || 0) === 1 ? '' : 's'} · ${Number(user.reputation || 0)} reputation</small></span><i>Message</i></button>`).join(''); const tradeRows = trades.map(trade => `<button type="button" class="delivery-row" data-trade-chat="${trade.id}"><strong>Trade · ${safe(trade.listing?.title || 'Collector listing')}</strong><span>${safe(trade.status)} · @${safe(trade.otherUser?.username || 'collector')}</span></button>`).join(''); const deliveryRows = currentDeliveries.map(delivery => `<button type="button" class="delivery-row" data-delivery="${delivery.id}"><strong>Delivery · ${safe(delivery.listing?.title || 'Collector order')}</strong><span>${safe(delivery.status.replaceAll('_', ' '))}</span></button>`).join(''); openModal('Messages', 'Talk with collectors, manage trade conversations, and find new people to follow.', `<section class="social-chat"><section class="chat-sidebar"><div class="chat-section-heading"><h3>Messages</h3><span>${conversations.length}</span></div><div class="conversation-list">${collectorRows || '<p class="modal-copy">Your direct messages will appear here.</p>'}</div><div class="chat-section-heading"><h3>Suggested collectors</h3><span>New</span></div><div class="suggestion-list">${suggestedRows || '<p class="modal-copy">You are already connected with every collector we can suggest.</p>'}</div></section><section class="chat-secondary"><h3>Trade & delivery</h3><div class="chat-resource-section"><h4>Trades</h4>${tradeRows || '<p class="modal-copy">No trade conversations yet.</p>'}</div><div class="chat-resource-section"><h4>Deliveries</h4>${deliveryRows || '<p class="modal-copy">No delivery conversations yet.</p>'}</div></section></section>`); modal.classList.add('chat-dialog'); document.body.classList.add('chat-open'); } catch (error) { openModal('Messages', error.message); } }
async function openCollectorChat(recipientId) { if (!session) return openAuthPanel('login'); const conversation = await api('/conversations', { method: 'POST', body: JSON.stringify({ recipientId }) }); await openConversation(conversation.id); }
