async function openTradeChat(id) { const trade = await api(`/trade/${id}`); const messages = trade.messages.length ? trade.messages.map(message => `<p class="post-comment ${message.senderId === session.user.id ? 'is-own-message' : ''}"><b>@${safe(message.senderId === session.user.id ? session.user.username : trade.otherUser?.username || 'collector')}</b><span>${safe(message.body)}</span></p>`).join('') : '<p class="modal-copy">No messages yet. Discuss the trade here.</p>'; const ownerControls = trade.receiverId === session.user.id && trade.status === 'pending' ? `<button type="button" data-trade-status="accepted" data-trade-id="${trade.id}">Accept trade</button><button type="button" data-trade-status="declined" data-trade-id="${trade.id}">Decline trade</button>` : ''; const completeControl = trade.status === 'accepted' ? `<button type="button" data-trade-status="completed" data-trade-id="${trade.id}">Mark trade completed</button>` : ''; openModal(`Trade · ${trade.listing?.title || 'Listing'}`, `Status: ${safe(trade.status)}`, `<section class="conversation-workspace trade-conversation-workspace"><header class="conversation-header"><button type="button" data-chat>← All messages</button><span class="trade-status">${safe(trade.status.replaceAll('_', ' '))}</span><strong>${safe(trade.listing?.title || 'Collector listing')}</strong><button type="button" class="voice-start" data-voice-room="trade:${trade.id}" data-voice-label="Trade voice · ${safe(trade.listing?.title || 'Listing')}">Start voice</button></header><section class="delivery-thread collector-thread trade-thread" aria-live="polite">${messages}</section><footer class="trade-actions">${ownerControls}${completeControl || '<span>Use this thread to coordinate the exchange.</span>'}</footer><form class="modal-form trade-message-form collector-message-form" data-trade="${trade.id}"><textarea required name="body" maxlength="500" placeholder="Message the other collector"></textarea><button type="submit">Send message</button></form></section>`); modal.classList.add('chat-dialog', 'trade-dialog'); document.body.classList.add('chat-open'); requestAnimationFrame(() => { const thread = modal.querySelector('.trade-thread'); if (thread) thread.scrollTop = thread.scrollHeight; modal.querySelector('.trade-message-form textarea')?.focus(); }); }
