async function loadDeliveries() { if (!session) { deliveries = []; return; } deliveries = await api('/deliveries'); }
async function openDeliveryCenter() { if (!session) return openAuthPanel('login'); try { await loadDeliveries(); const rows = deliveries.length ? deliveries.map(delivery => `<button type="button" class="delivery-row" data-delivery="${delivery.id}"><strong>${safe(delivery.listing?.title || 'Collector order')}</strong><span>${safe(delivery.status.replaceAll('_', ' '))}</span></button>`).join('') : '<p class="modal-copy">No deliveries yet. Purchases and sales will appear here.</p>'; openModal('Delivery center', 'Track dispatches, deliveries, messages, and issue reports.', `<section class="delivery-list">${rows}</section>`); } catch (error) { openModal('Delivery center', error.message); } }
async function openDelivery(id) { const delivery = await api(`/delivery/${id}`); const seller = delivery.sellerId === session?.user?.id; const steps = ['awaiting_seller_dispatch', 'packed', 'picked_up', 'in_transit', 'completed']; const labels = { awaiting_seller_dispatch: 'Order placed', packed: 'Packed', picked_up: 'Picked up', in_transit: 'In transit', completed: 'Delivered', issue_reported: 'Issue reported' }; const currentStep = steps.indexOf(delivery.status); const timeline = steps.map((step, index) => `<li class="${index < currentStep ? 'done' : index === currentStep ? 'current' : ''}"><i>${index < currentStep ? '✓' : index + 1}</i><span>${labels[step]}</span></li>`).join(''); const messages = delivery.messages.length ? delivery.messages.map(message => `<p class="post-comment"><b>@${safe(message.senderId === session.user.id ? session.user.username : seller ? delivery.buyer?.username : delivery.seller?.username || 'collector')}</b> ${safe(message.body)}</p>`).join('') : '<p class="modal-copy">No messages yet. Keep all delivery details in this thread.</p>'; const next = { awaiting_seller_dispatch: 'packed', packed: 'picked_up', picked_up: 'in_transit' }[delivery.status]; const sellerControls = seller && next ? `<form class="modal-form delivery-update-form" data-delivery="${delivery.id}"><h3>Seller action · ${labels[next]}</h3><input type="hidden" name="status" value="${next}"><input name="courier" value="${safe(delivery.courier || '')}" placeholder="Courier name${next === 'packed' ? ' (optional)' : ''}"><input name="trackingNumber" value="${safe(delivery.trackingNumber || '')}" placeholder="Tracking number${next === 'packed' ? ' (optional)' : ''}"><textarea name="note" maxlength="300" placeholder="Optional update for the buyer"></textarea><button>Mark as ${labels[next]}</button></form>` : seller ? '<p class="delivery-notice">No seller action is available for this delivery. Use the message thread for follow-up.</p>' : `<div class="delivery-buyer-actions">${delivery.status === 'in_transit' ? `<button type="button" class="auth-switch" data-delivery-confirm="${delivery.id}">Confirm delivery received</button>` : ''}${delivery.status !== 'completed' ? `<button type="button" class="auth-switch" data-delivery-issue="${delivery.id}">Report a delivery issue</button>` : ''}</div>`; const history = (delivery.history || []).slice().reverse().map(entry => `<li><b>${safe(labels[entry.status] || entry.status)}</b><span>${safe(entry.note || '')}</span><time>${safe(formatListingDate(entry.createdAt))}</time></li>`).join('') || '<li><span>Delivery updates will appear here.</span></li>'; openModal(`Delivery · ${delivery.listing?.title || 'Order'}`, `${seller ? `Buyer: @${safe(delivery.buyer?.username || 'collector')}` : `Seller: @${safe(delivery.seller?.username || 'collector')}`} · ${delivery.courier ? `${safe(delivery.courier)} · ` : ''}${delivery.trackingNumber ? `Tracking ${safe(delivery.trackingNumber)}` : 'Tracking pending'}`, `<section class="delivery-workspace"><ol class="delivery-timeline">${timeline}</ol><div class="delivery-address"><b>Delivery address</b><span>${safe(delivery.shippingAddress || '')}</span></div><section class="delivery-history"><h3>Updates</h3><ul>${history}</ul></section>${sellerControls}<section class="delivery-thread"><h3>Message thread</h3>${messages}</section><form class="modal-form delivery-message-form" data-delivery="${delivery.id}"><textarea required name="body" maxlength="500" placeholder="Message ${seller ? 'buyer' : 'seller'}"></textarea><button>Send message</button></form></section>`); }
function castVote(id, direction) { const state = stateFor(id); if (state.vote === direction) { state.score -= direction; state.vote = 0; } else { state.score += direction - state.vote; state.vote = direction; } savePostState(); renderFeed(); }
async function toggleFavorite(id) { if (!session) return openAuthPanel('login'); const result = await api(`/listing/${id}/favorite`, { method: 'POST', body: '{}' }); stateFor(id).favorite = result.favorited; savePostState(); renderFeed(); }
function money(value) { return `$${Number(value).toFixed(2)}`; }
function feeCalculator(item, type) {
  const trade = type === 'trade';
  const fields = trade ? `<label>Your trade valuation<input id="buyer-value" type="number" min="0" value="${item.price}"></label><label>Other side’s valuation<input id="seller-value" type="number" min="0" value="${item.price}"></label><label>Offer note<input required id="offer-note" placeholder="Describe the item you are offering"></label>` : `<label>Item price<input id="buyer-value" type="number" min="0" value="${item.price}" readonly aria-readonly="true"></label><label>Estimated buyer tax<input id="tax" type="number" min="0" value="0"></label><label>Courier packaging cost<input id="packaging" type="number" min="0" value="0"></label>`;
  const action = trade ? 'Send trade offer & open chat' : 'Place order & open delivery';
  const address = trade ? '' : '<label>Delivery address<textarea required id="shipping-address" maxlength="500" placeholder="Address for this delivery"></textarea></label>';
  const memberships = '<label class="check"><input id="buyer-curator" type="checkbox"> Buyer has Curator membership ($150/month)</label><label class="check"><input id="seller-curator" type="checkbox"> Seller has Curator membership ($150/month)</label>';
  if (trade) return `<form class="fee-calculator" data-type="${type}" data-listing="${item.id}">${fields}${memberships}<div id="fee-summary" class="fee-summary"></div><p class="policy-note">Policy draft: delivery, fraud, and enforcement rules require legal review before launch.</p><button type="submit" class="transaction-submit">${action}</button></form>`;
  const agreement = '<label class="check purchase-agreement"><input required type="checkbox" id="purchase-agreement"> I confirm this order and delivery address.</label>';
  return `<form class="fee-calculator purchase-checkout" data-type="${type}" data-listing="${item.id}"><section class="purchase-fields"><header><span>1</span><div><b>Delivery details</b><small>Confirm where this collector item should go.</small></div></header>${fields}${address}${memberships}</section><aside class="purchase-review"><header><span>2</span><div><b>Order review</b><small>Your order remains private until delivery is confirmed.</small></div></header><div id="fee-summary" class="fee-summary"></div>${agreement}<p class="policy-note">Placing an order reserves this listing and opens a private delivery thread with the seller. Payment collection is not enabled until the Square checkout connection is configured. Buyers pay taxes and shipping. Courier delivery pay is the greater of $15 or 0.5% of the valuation, plus documented packaging costs.</p><button type="submit" class="transaction-submit">${action}</button></aside></form>`;
}
function updateFeeSummary() {
  const box = document.querySelector('.fee-calculator'); if (!box) return;
  const type = box.dataset.type; const buyerValue = Number(document.querySelector('#buyer-value')?.value || 0); const sellerValue = Number(document.querySelector('#seller-value')?.value || buyerValue); const buyerRate = document.querySelector('#buyer-curator').checked ? .01 : .04; const sellerRate = document.querySelector('#seller-curator').checked ? .01 : .04; const tax = Number(document.querySelector('#tax')?.value || 0); const packaging = Number(document.querySelector('#packaging')?.value || 0); const courier = Math.max(15, buyerValue * .005) + packaging;
  document.querySelector('#fee-summary').innerHTML = type === 'trade' ? `<b>Trade valuation estimate</b><span>Buyer-side fee (${buyerRate * 100}%): ${money(buyerValue * buyerRate)}</span><span>Other-side fee (${sellerRate * 100}%): ${money(sellerValue * sellerRate)}</span><strong>Total valuation fees: ${money(buyerValue * buyerRate + sellerValue * sellerRate)}</strong>` : `<b>Purchase estimate</b><span>Buyer marketplace fee (${buyerRate * 100}%): ${money(buyerValue * buyerRate)}</span><span>Seller marketplace fee (${sellerRate * 100}%): ${money(buyerValue * sellerRate)}</span><span>Buyer tax: ${money(tax)} · Buyer shipping/courier: ${money(courier)}</span><strong>Buyer due: ${money(buyerValue + buyerValue * buyerRate + tax + courier)}</strong><strong>Seller fee: ${money(buyerValue * sellerRate)}</strong>`;
}
function setQuery(query) { activeQuery = query.trim(); search.value = activeQuery; document.querySelector('#clear-tags').hidden = !activeQuery; renderFeed(); }
const tagPath = tag => `/${String(tag).toLowerCase().trim().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}/`;
const routeTag = () => {
  const slug = decodeURIComponent(location.pathname).replace(/^\/+|\/+$/g, '').toLowerCase();
  if (!slug || slug.includes('/')) return '';
  const knownTags = [...new Set([...categoryOptions, ...Object.values(tagGroups).flat(), ...listings.flatMap(listingTags)])];
  return knownTags.find(tag => tagPath(tag) === `/${slug}/`) || '';
};
const syncTagRoute = (replace = false) => {
  const path = activeTags.length === 1 ? tagPath(activeTags[0]) : '/';
  if (location.pathname === path) return;
  history[replace ? 'replaceState' : 'pushState']({}, '', path);
};
const applyTagRoute = () => { const tag = routeTag(); activeTags = tag ? [tag.toLowerCase()] : []; setDiscoveryMode(tag ? 'tags' : 'search'); renderTags(); renderFeed(); };
function toggleTag(tag, multiSelect = false) { const value = tag.toLowerCase(); if (multiSelect) activeTags = activeTags.includes(value) ? activeTags.filter(current => current !== value) : [...activeTags, value]; else activeTags = activeTags.length === 1 && activeTags[0] === value ? [] : [value]; syncTagRoute(); renderTags(); renderFeed(); }
